function Get-DatastoreRisk {
  param([int]$Threshold = 85)
  Get-Datastore | ForEach-Object {
    $used = [math]::Round((1 - $_.FreeSpaceGB / $_.CapacityGB) * 100, 1)
    if ($used -ge $Threshold) { [PSCustomObject]@{Name=$_.Name; UsedPct=$used} }
  }
}
